import { useState } from 'react';
import { JxButton, JxDivider, JxDrawer } from '@jinx-ui/react';

export type NavKey = 'projects' | 'team' | 'settings' | 'logout';

interface MenuDrawerProps {
  onNavigate: (key: NavKey) => void;
}

const NAV_ITEMS: ReadonlyArray<{ key: NavKey; label: string }> = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function MenuDrawer({ onNavigate }: MenuDrawerProps) {
  const [open, setOpen] = useState(false);

  const select = (key: NavKey) => {
    setOpen(false);
    onNavigate(key);
  };

  const itemStyle = { width: '100%', justifyContent: 'flex-start' } as const;

  return (
    <>
      <JxButton variant="secondary" onClick={() => setOpen(true)}>
        Меню
      </JxButton>

      <JxDrawer
        open={open}
        onOpenChange={setOpen}
        side="left"
        title="Меню"
        aria-label="Меню навигации"
      >
        <nav
          aria-label="Основная навигация"
          style={{ display: 'grid', gap: 'var(--jx-space-1)' }}
        >
          {NAV_ITEMS.map((item) => (
            <JxButton
              key={item.key}
              variant="ghost"
              style={itemStyle}
              onClick={() => select(item.key)}
            >
              {item.label}
            </JxButton>
          ))}

          <JxDivider />

          <JxButton
            variant="danger"
            style={itemStyle}
            onClick={() => select('logout')}
          >
            Выйти
          </JxButton>
        </nav>
      </JxDrawer>
    </>
  );
}

